<?php $layoutTitle='Audit trail';$layoutPage='audit';require dirname(__DIR__).'/layouts/start.php'; ?><h1>Audit trail</h1><p><?=$canViewAllActivity?'Append-only system events.':'Your own recorded system events.'?> Times are UTC. Passwords, session tokens and reset tokens are excluded.</p><?php if($error):?><p class="error" role="alert"><?=access_h($error)?></p><?php endif?><form method="get" class="card"><div class="grid"><?php foreach(['action'=>'Action code','outcome'=>'Outcome','actor'=>'Actor staff ID','start'=>'Start date (UTC)','end'=>'End date (UTC)'] as $key=>$label):if($key==='actor'&&!$canViewAllActivity)continue;?><div><label for="<?=access_h($key)?>"><?=access_h($label)?></label><input id="<?=access_h($key)?>" name="<?=access_h($key)?>" type="<?=in_array($key,['start','end'])?'date':'text'?>" value="<?=access_h(is_string($_GET[$key] ?? null)?$_GET[$key]:'')?>"></div><?php endforeach?></div><p><button>Apply filters</button> <a href="audit.php">Clear</a></p></form><div class="card scroll"><table><thead><tr><th>Event / UTC time</th><th>Actor</th><th>Action / target</th><th>Outcome</th><th>Details</th></tr></thead><tbody><?php foreach($events as $event):?><tr><td>#<?=(int)$event['id']?><br><?=access_h(display_date($event['occurred_at']))?><br><small>Request <?=access_h($event['request_id'])?></small></td><td><?=$event['actor_id']?'#'.(int)$event['actor_id'].' '.access_h($event['actor_name']):'Unauthenticated / system'?></td><td><?=access_h($event['action'])?><br><?=access_h($event['target_type'])?> <?=access_h($event['target_id'])?></td><td><?=access_h($event['outcome'])?></td><td><pre><?=access_h($event['details'])?></pre></td></tr><?php endforeach?><?php if(!$events):?><tr><td colspan="5">No matching events.</td></tr><?php endif?></tbody></table></div><?php if(count($events)===100): $filters=$_GET;$filters['before']=(string)end($events)['id'];?><a class="button" href="?<?=access_h(http_build_query($filters))?>">Older events</a><?php endif?><?php require dirname(__DIR__).'/layouts/end.php'; ?>